    {"rule_id": "TR-005", "rule_name": "Share Transfer Violates AoA Restriction — BLACK OVERRIDE", "rule_type": "THRESHOLD", "statutory_basis": "Section 38; AoA, Companies Act 1994 (Bangladesh)", "description": "Transfer executed in violation of AoA restriction — pre-emption rights not offered, prohibited transferee, or board approval refused. Transfer is void ab initio. Transferee has no legal title. Rectification requires court order or unanimous ratification. BLACK OVERRIDE: forces score to BLACK band. Corporate Rescue mandatory.", "rule_condition": {"check_fn": "check_tr_005", "trigger": "aoa_violated == True", "data_points": ["share_transfers", "aoa_violated"]}, "default_severity": "BLACK", "score_impact": 15, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "TR-006", "rule_name": "Composite Irregular Transfer", "rule_type": "CASCADE", "statutory_basis": "Sections 34, 47, 108, Companies Act 1994 (Bangladesh)", "description": "Transfer has 2+ concurrent deficiencies from TR-001 to TR-005. Composite irregularity compounds legal risk. Each deficiency may independently void transfer. Together they indicate systemic share administration failure requiring structured remediation.", "rule_condition": {"check_fn": "check_tr_006", "trigger": "is_irregular == True AND irregularity_count >= 2", "data_points": ["share_transfers", "is_irregular"]}, "default_severity": "RED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},

    # MODULE 7: STATUTORY REGISTERS — 3 rules (Sec 34, 83, 87, 90)
    {"rule_id": "REG-001", "rule_name": "Statutory Registers Incomplete", "rule_type": "THRESHOLD", "statutory_basis": "Section 34, Companies Act 1994 (Bangladesh)", "description": "One or more of 7 mandatory statutory registers not maintained at registered office. Required: Members (Sec 34), Directors (Sec 90), Charges (Sec 87), Transfers (Sec 108), Debentures (Sec 90), AGM Minutes (Sec 83), Board Minutes (Sec 90). Failure is criminal offence; officers personally liable.", "rule_condition": {"check_fn": "check_reg_001", "trigger": "len(maintained_registers) < 7", "data_points": ["maintained_registers"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "REG-002", "rule_name": "Core Statutory Registers Missing", "rule_type": "THRESHOLD", "statutory_basis": "Sections 34, 89, 115, 174, Companies Act 1994 (Bangladesh)", "description": "Core statutory records missing. Distinguishes (1) internal register-keeping obligations — Members (Sec 34), Meeting minutes (Sec 89), Charges register (Sec 174) — from (2) RJSC filing obligations such as director particulars (Sec 115). Each missing item is an independent legal obligation. Absence of internal registers is a governance failure; missing RJSC filings are separate filing defaults.", "rule_condition": {"check_fn": "check_reg_002", "trigger": "members_register_missing OR directors_register_missing OR charges_register_missing OR minutes_agm_missing OR related RJSC filing gaps", "data_points": ["register_of_members_maintained", "register_of_directors_maintained", "register_of_charges_maintained", "minutes_book_agm_maintained"]}, "default_severity": "RED", "score_impact": 12, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "REG-003", "rule_name": "Registers Not Kept at Registered Office", "rule_type": "THRESHOLD", "statutory_basis": "Section 34(2), Companies Act 1994 (Bangladesh)", "description": "Statutory registers not at registered office. Section 34(2): registers must be at registered office unless RJSC notified of alternative location. Alternative must be in Bangladesh and Board-approved. Registers open to inspection during business hours.", "rule_condition": {"check_fn": "check_reg_003", "trigger": "register_location != registered_office AND alternative_location_notified == False", "data_points": ["register_location", "alternative_location_notified"]}, "default_severity": "YELLOW", "score_impact": 3, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 8: REGISTERED OFFICE — 1 rule (Sec 77, Form VI, 28 days)
    {"rule_id": "OFF-001", "rule_name": "Change of Registered Office Not Filed Within 28 Days", "rule_type": "DEADLINE", "statutory_basis": "Section 77, Companies Act 1994 (Bangladesh)", "description": "Office change not filed via Form VI within 28 days. Section 77 requires 28-day filing (NOT 30 days). Until filed, old address remains legal registered office. Statutory notices served there are valid.", "rule_condition": {"check_fn": "check_off_001", "trigger": "registered_office_change_date IS NOT NULL AND form_vi_filed == False AND days_since_office_change > 28", "data_points": ["registered_office_change_date", "form_vi_filed"]}, "default_severity": "YELLOW", "score_impact": 3, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 9: CAPITAL & CHARGES — 4 rules (Sec 54, 87, 52)
    {"rule_id": "CAP-001", "rule_name": "Capital Alteration Without Proper Resolution", "rule_type": "CASCADE", "statutory_basis": "Section 53, Companies Act 1994 (Bangladesh)", "description": "Capital alteration without required board/special resolution, or forms not filed. Section 54 governs capital increase procedure. Unrecorded changes cause RJSC register to differ from actual capital, creating legal uncertainty.", "rule_condition": {"check_fn": "check_cap_001", "trigger": "capital_increase_date IS NOT NULL AND capital_increase_resolution == False", "data_points": ["capital_increase_date", "capital_increase_resolution"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-002", "rule_name": "Charge Not Registered With RJSC Within 21 Days", "rule_type": "DEADLINE", "statutory_basis": "Section 159(1), Companies Act 1994 (Bangladesh)", "description": "Charge created but not registered via Form XVIII within 21 days under Section 159. Assess the charge instrument, date of creation, registrability, any statutory extension and RJSC certificate; do not infer all consequences from a missing upload.", "rule_condition": {"check_fn": "check_cap_002", "trigger": "charge_creation_date IS NOT NULL AND form_xviii_filed == False AND days_since_charge_creation > 21", "data_points": ["charge_creation_date", "form_xviii_filed"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-003", "rule_name": "Capital Reduction — Court Confirmation Review", "rule_type": "CASCADE", "statutory_basis": "Sections 59-60, Companies Act 1994 (Bangladesh)", "description": "A pending capital-reduction workflow without verified court-confirmation evidence requires lawyer review. A pending workflow alone does not prove an unlawful completed reduction.", "rule_condition": {"check_fn": "check_cap_003", "trigger": "capital_reduction_pending == True AND capital_reduction_court_order_obtained == False", "data_points": ["capital_reduction_pending", "capital_reduction_court_order_obtained"]}, "default_severity": "YELLOW", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-004", "rule_name": "Special Resolution Not Filed With RJSC", "rule_type": "DEADLINE", "statutory_basis": "Section 88(1), Companies Act 1994 (Bangladesh) — 15 days", "description": "Copy of a special or extraordinary resolution must be filed with RJSC within 15 days under Section 88(1). This filing duty does not by itself determine whether every underlying transaction is valid or complete.", "rule_condition": {"check_fn": "check_cap_004", "trigger": "special_resolution_date IS NOT NULL AND form_viii_filed == False AND days_since_resolution > 15", "data_points": ["special_resolution_date", "form_viii_filed"]}, "default_severity": "YELLOW", "score_impact": 8, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 10: TAX — 2 rules (Income Tax Act 2023, VAT Act 2012)
    {"rule_id": "TAX-001", "rule_name": "Tax Identification Number (TIN) Not Obtained", "rule_type": "THRESHOLD", "statutory_basis": "Income Tax Act 2023 (Bangladesh)", "description": "No TIN from NBR. Income Tax Act 2023: TIN mandatory for all companies. Without TIN: cannot file returns, open bank accounts, obtain import licenses, participate in tenders, or claim exemptions. Directors may face liability for trading without TIN.", "rule_condition": {"check_fn": "check_tax_001", "trigger": "tin_obtained == False", "data_points": ["tin_obtained", "tin_number"]}, "default_severity": "RED", "score_impact": 10, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "TAX-002", "rule_name": "VAT Registration or Turnover-Tax Enlistment Status Requires Verification", "rule_type": "CONDITIONAL", "statutory_basis": "Value Added Tax and Supplementary Duty Act 2012, as amended by Act No. 77 of 2026; exact current section and taxpayer-specific instruments require counsel verification", "description": "Review prompt only. Verify rolling 12-month taxable turnover, mandatory-registration categories and taxpayer activity. Above BDT 30 lakh up to BDT 50 lakh may require turnover-tax enlistment; above BDT 50 lakh may require VAT registration. Verify the 30-day application period and effective date before any breach finding.", "rule_condition": {"check_fn": "check_tax_002", "trigger": "vat_registered == False AND reported_annual_turnover_bdt > 3000000", "data_points": ["vat_registered", "annual_turnover_bdt"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 11: ESCALATION — 3 rules (Sec 304, NOT 396)
    {"rule_id": "ESC-001", "rule_name": "Strike-Off Risk Elevated", "rule_type": "ESCALATION", "statutory_basis": "Section 346, Companies Act 1994 (Bangladesh)", "description": "Compliance profile shows RJSC strike-off criteria under Section 304: multi-year missed filings, no recent trading, or RED flags across 3+ modules. Section 304 permits strike-off for non-filing or non-trading. Structured Regularization required immediately.", "rule_condition": {"check_fn": "check_esc_001", "trigger": "unfiled_returns_count >= 2 OR (active_red_flags >= 3 AND active_yellow_flags >= 4)", "data_points": ["unfiled_returns_count", "active_red_flags", "active_yellow_flags"]}, "default_severity": "RED", "score_impact": 15, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "ESC-002", "rule_name": "Strike-Off Imminent — BLACK OVERRIDE", "rule_type": "ESCALATION", "statutory_basis": "Section 346, Companies Act 1994 (Bangladesh)", "description": "Immediate RJSC strike-off risk. Criteria: 3+ years non-filing, strike-off notice received, or on published strike-off list. Once struck off: company ceases to exist, contracts void, accounts frozen. Restoration requires court proceedings under Section 305. Corporate Rescue mandatory. BLACK OVERRIDE: forces score to BLACK band.", "rule_condition": {"check_fn": "check_esc_002", "trigger": "unfiled_returns_count >= 3 OR rjsc_strike_off_notice == True OR on_rjsc_strike_off_list == True", "data_points": ["unfiled_returns_count", "rjsc_strike_off_notice", "on_rjsc_strike_off_list"]}, "default_severity": "BLACK", "score_impact": 25, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "ESC-003", "rule_name": "Corporate Rescue Mandatory — Systemic Failure", "rule_type": "ESCALATION", "statutory_basis": "NLC internal risk policy; not a statutory Companies Act risk classification", "description": "Internal BLACK escalation and rescue workflow. A BLACK classification, score threshold and rescue deadline are NLC policy decisions, not statutory consequences. Policy-owner approval is required.", "rule_condition": {"check_fn": "check_esc_003", "trigger": "pre_override_score <= 29 OR has_black_override == True", "data_points": ["pre_override_score", "has_black_override", "active_red_flags", "active_black_flags"]}, "default_severity": "BLACK", "score_impact": 10, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    # ═══════════════════════════════════════════════════════════════
    # EXTENDED RULES (synced from engine.py – 29 rules previously missing)
    # ═══════════════════════════════════════════════════════════════

    {"rule_id": "AGM-007", "rule_name": "AGM Adjourned Without Proper Notice", "rule_type": "THRESHOLD", "statutory_basis": "Section 85, Companies Act 1994 (Bangladesh)", "description": "AGM adjourned without proper notice. Section 84.", "rule_condition": {"check_fn": "check_agm_007", "trigger": "agm_adjourned_without_notice == True", "data_points": ["agm_adjourned_without_notice"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "AUD-005", "rule_name": "Subsequent Auditor Reappointment Status Unknown", "rule_type": "DEPENDENCY", "statutory_basis": "Section 210(3), Companies Act 1994 (Bangladesh)", "description": "No verified record establishes whether the retiring auditor was reappointed or a statutory exception applied. Evidence-status only; no 120-day deadline.", "rule_condition": {"check_fn": "check_aud_005", "trigger": "agm_held_this_cycle == True AND auditor_reappointed_at_agm IS NULL", "data_points": ["agm_held_this_cycle", "auditor_reappointed_at_agm"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "BNK-001", "rule_name": "Winding Up Petition Filed", "rule_type": "THRESHOLD", "statutory_basis": "Bankruptcy Act 1997 (Bangladesh), Section 12", "description": "Winding up petition filed against company. Company under court supervision.", "rule_condition": {"check_fn": "check_bnk_001", "trigger": "winding_up_petition_filed == True", "data_points": ["winding_up_petition_filed"]}, "default_severity": "BLACK", "score_impact": 25, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "BNK-002", "rule_name": "Liquidator Appointed", "rule_type": "THRESHOLD", "statutory_basis": "Bankruptcy Act 1997 (Bangladesh), Section 14", "description": "Liquidator appointed. Company under liquidation proceedings.", "rule_condition": {"check_fn": "check_bnk_002", "trigger": "liquidator_appointed == True", "data_points": ["liquidator_appointed"]}, "default_severity": "BLACK", "score_impact": 25, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "BNK-003", "rule_name": "Court-Ordered Winding Up", "rule_type": "THRESHOLD", "statutory_basis": "Bankruptcy Act 1997 (Bangladesh), Section 18", "description": "Court-ordered winding up. Company being wound up by court order.", "rule_condition": {"check_fn": "check_bnk_003", "trigger": "court_ordered_winding_up == True", "data_points": ["court_ordered_winding_up"]}, "default_severity": "BLACK", "score_impact": 35, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "BSEC-001", "rule_name": "BSEC Quarterly Report Status Requires Verification", "rule_type": "DEADLINE", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Review prompt only: verify the exact BSEC reporting instrument, listed issuer class, reporting period and due date; this is not Corporate Governance Code Condition 8.", "rule_condition": {"check_fn": "check_bsec_001", "trigger": "bsec_listed == True AND bsec_quarterly_report_filed == False", "data_points": ["bsec_listed", "bsec_quarterly_report_filed"], "conditional": True}, "default_severity": "RED", "score_impact": 10, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "BSEC-002", "rule_name": "CG Certificate Not Obtained", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Corporate Governance certificate not obtained (listed companies).", "rule_condition": {"check_fn": "check_bsec_002", "trigger": "bsec_listed == True AND cg_certificate_obtained == False", "data_points": ["bsec_listed", "cg_certificate_obtained"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "BSEC-003", "rule_name": "Board Composition Non-Compliant", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Board composition non-compliant (independent director requirement).", "rule_condition": {"check_fn": "check_bsec_003", "trigger": "bsec_listed == True AND board_independent_director == False", "data_points": ["bsec_listed", "board_independent_director"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "BSEC-004", "rule_name": "Audit Committee Not Established", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Audit committee not established (listed companies).", "rule_condition": {"check_fn": "check_bsec_004", "trigger": "bsec_listed == True AND audit_committee_established == False", "data_points": ["bsec_listed", "audit_committee_established"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CHG-001", "rule_name": "Charge Satisfaction Not Filed", "rule_type": "DEADLINE", "statutory_basis": "Section 172, Companies Act 1994 (Bangladesh)", "description": "Charge satisfaction filing via Form XXVIII within 21 days, subject to verification of satisfaction date and RJSC receipt.", "rule_condition": {"check_fn": "check_chg_001", "trigger": "charge_satisfied == True AND satisfaction_filed == False", "data_points": ["charges"]}, "default_severity": "YELLOW", "score_impact": 3, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "DEF-001", "rule_name": "Director Disqualified", "rule_type": "THRESHOLD", "statutory_basis": "Section 94, Companies Act 1994 (Bangladesh)", "description": "Director disqualification requires a specified Section 94 or Articles ground, director identity, authoritative evidence, effective date and continuing status. Unpaid-call ground remains DISPUTED: official Bengali text says 180 days, while English/case materials say six months. Do not automatically classify until a Bangladesh company-law reviewer resolves the discrepancy. Section 94 does not prescribe a universal five-year ban. This finding is not an automatic BLACK override and remains outside production scoring pending independent legal approval.", "rule_condition": {"check_fn": "check_def_001", "trigger": "structured verified disqualification_grounds with all required evidence fields", "data_points": ["disqualification_grounds", "director_name", "evidence_ref", "authority", "effective_date", "continuing_status"]}, "default_severity": "RED", "score_impact": 10, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "DEF-002", "rule_name": "Unresolved Penalty Notices", "rule_type": "ESCALATION", "statutory_basis": "Section 397, Companies Act 1994 (Bangladesh)", "description": "Unresolved penalty notices. Section 447: fine up to Tk 10,000 per offence.", "rule_condition": {"check_fn": "check_def_002", "trigger": "penalty_notices_received > penalty_notices_resolved", "data_points": ["penalty_notices_received", "penalty_notices_resolved"]}, "default_severity": "YELLOW", "score_impact": 8, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "DIR-005", "rule_name": "Register of Directors Interests Missing", "rule_type": "THRESHOLD", "statutory_basis": "Section 130, Companies Act 1994 (Bangladesh)", "description": "Register of directors interests not maintained. Section 97.", "rule_condition": {"check_fn": "check_dir_005", "trigger": "register_of_directors_interests == False", "data_points": ["register_of_directors_interests"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "DIR-006", "rule_name": "Register of Contracts Missing", "rule_type": "THRESHOLD", "statutory_basis": "Section 130, Companies Act 1994 (Bangladesh)", "description": "Register of contracts not maintained. Section 98.", "rule_condition": {"check_fn": "check_dir_006", "trigger": "register_of_contracts == False", "data_points": ["register_of_contracts"]}, "default_severity": "YELLOW", "score_impact": 5, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "ESC-004", "rule_name": "Voluntary Winding Up", "rule_type": "THRESHOLD", "statutory_basis": "Section 286, Companies Act 1994 (Bangladesh)", "description": "Voluntary winding up initiated. Section 196.", "rule_condition": {"check_fn": "check_esc_004", "trigger": "voluntary_winding_up == True", "data_points": ["voluntary_winding_up"]}, "default_severity": "BLACK", "score_impact": 30, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": True},
    {"rule_id": "ESC-005", "rule_name": "Investigation Order Pending", "rule_type": "THRESHOLD", "statutory_basis": "Section 195, Companies Act 1994 (Bangladesh)", "description": "Investigation order pending under Section 199.", "rule_condition": {"check_fn": "check_esc_005", "trigger": "investigation_order == True", "data_points": ["investigation_order"]}, "default_severity": "RED", "score_impact": 20, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "FX-001", "rule_name": "Foreign Exchange Violation", "rule_type": "THRESHOLD", "statutory_basis": "Foreign Exchange Regulation Act 1947 (Bangladesh)", "description": "Foreign exchange violation detected under FE Regulation Act 1947.", "rule_condition": {"check_fn": "check_fx_001", "trigger": "foreign_exchange_violation == True", "data_points": ["foreign_exchange_violation"]}, "default_severity": "RED", "score_impact": 15, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "LBR-001", "rule_name": "Factory License Missing", "rule_type": "THRESHOLD", "statutory_basis": "Bangladesh Labour Act 2006, Section 326, as amended by Act No. 43 of 2026", "description": "Review prompt only: verify a Government direction under section 326, establishment class, effective date, exemptions and authentic licence status.", "rule_condition": {"check_fn": "check_lbr_001", "trigger": "factory_license_required_by_direction == True AND factory_license_obtained == False", "data_points": ["factory_license_obtained"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "LBR-002", "rule_name": "Factory License Expired", "rule_type": "DEADLINE", "statutory_basis": "Bangladesh Labour Act 2006, Section 326, as amended by Act No. 43 of 2026", "description": "Review prompt only: verify the section 326 Government direction, licence class, five-year/contractor one-year term, renewal application and any extension.", "rule_condition": {"check_fn": "check_lbr_002", "trigger": "factory_license_required_by_direction == True AND factory_license_expiry < today", "data_points": ["factory_license_expiry"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "LBR-003", "rule_name": "Labour Court Order Pending", "rule_type": "THRESHOLD", "statutory_basis": "Labour Act 2006 (Bangladesh), Section 209", "description": "Labour court order pending against the company.", "rule_condition": {"check_fn": "check_lbr_003", "trigger": "labour_court_order_pending == True", "data_points": ["labour_court_order_pending"]}, "default_severity": "RED", "score_impact": 15, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
